1. using Microsoft.ML;
2. using Microsoft.ML.Data;
3. using TicketClassifier.Models;
4. 
5. namespace TicketClassifier.Services;
6. 
7. public class TicketClassifierService
8. {
9.     private readonly MLContext _mlContext;
10.     private readonly ITransformer _model;
11.     private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
12.     private readonly EvaluationMetrics _metrics;
13.     private readonly string[] _categoryLabels;
14. 
15.     public TicketClassifierService()
16.     {
17.         _mlContext = new MLContext(seed: 0);
18. 
19.         var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
20.         var dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
21.             dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);
22. 
23.         var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category))
24.             .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
25.             .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
26.             .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
27.             .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
28.             .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));
29. 
30.         _model = pipeline.Fit(dataView);
31. 
32.         // Evaluate on training data
33.         var predictions = _model.Transform(dataView);
34.         var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, "Label");
35.         _metrics = new EvaluationMetrics
36.         {
37.             MacroAccuracy = (float)metrics.MacroAccuracy,
38.             MicroAccuracy = (float)metrics.MicroAccuracy,
39.             LogLoss = (float)metrics.LogLoss,
40.             LogLossReduction = (float)metrics.LogLossReduction
41.         };
42. 
43.         // Extract category labels in the order assigned by MapValueToKey
44.         // by transforming only up to the key mapping step and reading annotations
45.         var keyMappingPipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category));
46.         var keyMappingTransformer = keyMappingPipeline.Fit(dataView);
47.         var keyMappedData = keyMappingTransformer.Transform(dataView);
48.         var labelSchema = keyMappedData.Schema["Label"];
49.         
50.         // The annotations on a Key column contain "KeyValues" 
51.         var annoSchema = labelSchema.Annotations.Schema;
52.         if (annoSchema.Count > 0)
53.         {
54.             var keyValues = new VBuffer<ReadOnlyMemory<char>>();
55.             labelSchema.Annotations.GetValue("KeyValues", ref keyValues);
56.             _categoryLabels = keyValues.DenseValues().Select(v => v.ToString()).ToArray();
57.         }
58.         else
59.         {
60.             _categoryLabels = _mlContext.Data.CreateEnumerable<TicketData>(dataView, reuseRowObject: false)
61.                 .Select(t => t.Category).Distinct().ToArray();
62.         }
63. 
64.         _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(_model);
65.     }
66. 
67.     public PredictionResponse Predict(TicketRequest request)
68.     {
69.         var ticketData = new TicketData
70.         {
71.             Subject = request.Subject,
72.             Description = request.Description,
73.             Priority = request.Priority
74.         };
75. 
76.         var prediction = _predictionEngine.Predict(ticketData);
77. 
78.         var confidence = new Dictionary<string, float>();
79.         for (int i = 0; i < _categoryLabels.Length && i < prediction.Score.Length; i++)
80.         {
81.             confidence[_categoryLabels[i]] = prediction.Score[i];
82.         }
83. 
84.         return new PredictionResponse
85.         {
86.             PredictedCategory = prediction.PredictedCategory,
87.             Confidence = confidence
88.         };
89.     }
90. 
